import { MakeLogicType, actions, kea, key, listeners, path, props, reducers } from 'kea'
import posthog from 'posthog-js'

interface NotebookExportLogicProps {
    shortId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface notebookExportLogicValues {
    preparingPrint: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface notebookExportLogicActions {
    cancelPrint: () => {
        value: true
    }
    preparePrint: () => {
        value: true
    }
    printNotebook: (title: string) => {
        title: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface notebookExportLogicMeta {
    key: string
}

export type notebookExportLogicType = MakeLogicType<
    notebookExportLogicValues,
    notebookExportLogicActions,
    NotebookExportLogicProps,
    notebookExportLogicMeta
>

export const notebookExportLogic = kea<notebookExportLogicType>([
    props({} as NotebookExportLogicProps),
    key(({ shortId }) => shortId),
    path((key) => ['products', 'notebooks', 'notebookExportLogic', key]),
    actions({ preparePrint: true, cancelPrint: true, printNotebook: (title: string) => ({ title }) }),
    reducers({ preparingPrint: [false, { preparePrint: () => true, cancelPrint: () => false }] }),
    listeners(({ props, cache }) => ({
        printNotebook: ({ title }) => {
            const notebook = document.querySelector<HTMLElement>(
                `.Notebook[data-notebook-short-id="${CSS.escape(props.shortId)}"]`
            )
            if (!notebook) {
                return
            }
            cache.disposables.add(
                () => {
                    const originalTitle = document.title
                    const ancestors: HTMLElement[] = []
                    for (let parent = notebook.parentElement; parent; parent = parent.parentElement) {
                        ancestors.push(parent)
                        parent.classList.add('NotebookPrintAncestor')
                    }
                    notebook.classList.add('Notebook--printing')
                    document.title = title
                    const finish = (): void => cache.disposables.dispose('print')
                    window.addEventListener('afterprint', finish)
                    return () => {
                        window.removeEventListener('afterprint', finish)
                        notebook.classList.remove('Notebook--printing')
                        ancestors.forEach((parent) => parent.classList.remove('NotebookPrintAncestor'))
                        document.title = originalTitle
                    }
                },
                'print',
                { pauseOnPageHidden: false }
            )
            posthog.capture('notebook export requested', { format: 'pdf', short_id: props.shortId })
            try {
                window.print()
            } catch (error) {
                cache.disposables.dispose('print')
                throw error
            }
        },
    })),
])
